import json
import re
from os.path import basename

from ute_common_util.multidict import MultiDict

from ..utils.logger import logger
from .validator import ConfigValidator


class Config:

    def __init__(self, data, *args, **kwargs):
        """
        :param string data: "JSON-like" data.
        """
        self._data = self._translate_to_dict(data)
        self._validation_result = False
        self._suite_path = None
        self._test_name = None
        self._build_label = None
        self._sw_version = None

    def validate(self):
        """Validate configuration."""
        if self._data:
            self._validate()

    def is_valid(self):
        """Return validation result."""
        return self._validation_result

    def get_qc(self, sw_version, test_name, label, suite_path=""):
        """Get proper QC instance selected based on provided information.

        :param string   sw_version:   eNB software version.
        :param string   test_name:    Robot Framework test name.
        :param string   label:        Label of testline.
        :param string   suite_path:   Path to suite.

        :return:    List of matched items and matched flag
        :rtype:     tuple
        """
        if not self.is_valid() or not sw_version:
            return [
                {"qc_path": "", "qc_test_set": "", "qc_domain": "", "qc_project": ""}
            ], False
        self._sw_version, self._test_name, self._build_label = (
            sw_version,
            test_name,
            label,
        )
        self._suite_path = basename(suite_path)
        qc_data = self._get_sw_version_part()
        if not qc_data:
            return [
                {"qc_path": "", "qc_test_set": "", "qc_domain": "", "qc_project": ""}
            ], False
        matched_entries = self._search_for_test_name_data(qc_data)
        return matched_entries, True

    @staticmethod
    def _translate_to_dict(data):
        try:
            return json.loads(data, object_pairs_hook=MultiDict)
        except ValueError as e:
            logger.error(
                f"QC configuration has wrong format. JSON format only supported. Returned error:\n{e}"
            )

    def _validate(self):
        self._validation_result = ConfigValidator().validate(self._data)

    def _get_sw_version_part(self):
        sw_version_matched_data = []
        for branch_name, data in list(self._data.items()):
            regexp = self._prepare_regexp(branch_name)
            if re.search(regexp, self._sw_version):
                if self._is_label_matched(data, self._build_label):
                    sw_version_matched_data.append(data)
        return sw_version_matched_data

    @staticmethod
    def _is_label_matched(qc_data, label):
        if label is None or "label" not in qc_data:
            return True
        else:
            label_regex = qc_data["label"]
            return True if re.match(label_regex, label) else False

    def _search_for_test_name_data(self, sw_load):
        test_qc_data = []
        for qc_data in sw_load:
            for qc_path, qc_path_value in list(qc_data.items()):
                if qc_path not in ["label", "qc_domain", "qc_project"]:
                    qc_test_set = self._match_test_name_with_test_set(
                        qc_data, qc_path_value
                    )
                    if qc_test_set:
                        qc_domain, qc_project = self._search_for_domain_and_project(
                            qc_data
                        )
                        test_qc_data.append(
                            {
                                "qc_path": qc_path,
                                "qc_test_set": qc_test_set,
                                "qc_domain": qc_domain,
                                "qc_project": qc_project,
                            }
                        )
        if not test_qc_data:
            test_qc_data.append(
                {"qc_path": "", "qc_test_set": "", "qc_domain": "", "qc_project": ""}
            )
        return test_qc_data

    def _match_test_name_with_test_set(self, qc_data, qc_path_value):
        for qc_test_set, test_instance_regexps in list(qc_path_value.items()):
            qc_test_set = self._match_test_set(qc_test_set, test_instance_regexps)
            if qc_test_set:
                if self._build_label and "label" in qc_data:
                    logger.info(
                        f'LABEL: "{self._build_label}" matched for "{self._test_name[:150]}"'
                    )
                return qc_test_set

    def _match_test_set(self, qc_test_set, test_instance_regexps):
        for each in test_instance_regexps:
            if each.find(":") != -1:
                robot_file, each = each.split(":", 1)
                if robot_file != self._suite_path:
                    continue
            regexp = self._prepare_regexp(each)
            try:
                if re.search(regexp, self._test_name):
                    return qc_test_set
            except re.error:
                logger.warning("Please check your .qc file regexes")
                break

    @staticmethod
    def _search_for_domain_and_project(qc_data: dict) -> tuple[str, str]:
        qc_domain, qc_project = "", ""
        for qc_path, qc_path_value in list(qc_data.items()):
            if qc_path == "qc_domain":
                qc_domain = qc_path_value
            if qc_path == "qc_project":
                qc_project = qc_path_value
        return qc_domain, qc_project

    @staticmethod
    def _prepare_regexp(regexp: str) -> str:
        regexp = re.escape(regexp)
        regexp = regexp.replace(r"\.", ".")
        regexp = regexp.replace(r"\*", "*")
        regexp = regexp.replace(r"\?", "?")
        regexp = regexp.replace(r"\+", "+")
        regexp = regexp.replace(r"\|", "|")
        regexp = regexp.replace(r"\$", "$")
        return regexp


class ConfigsStore:

    def __init__(self, configs):
        self.configs = self._remove_empty_configs(configs)

    def __iter__(self):
        return (config for config in self.configs)

    def __bool__(self):
        return True if self.configs else False

    def to_dicts(self) -> list[dict]:
        """Return serialized list of configs"""
        configs_dicts = []
        for config in self.configs:
            for config_entry in config:
                configs_dicts.append(self._serialize_config(config_entry))
        return configs_dicts

    @staticmethod
    def _serialize_config(config):
        return {
            "test_lab_path": config.test_lab_path,
            "test_set_name": config.test_set_name,
            "test_instance_name": config.test_instance_name,
            "test_instance_id": config.test_instance_id,
            "qc_domain": config.qc_domain,
            "qc_project": config.qc_project,
        }

    @staticmethod
    def _remove_empty_configs(configs):
        return [config for config in configs if config]
